import UIKit

/// Icônes de la barre Liquid Glass, intégrées directement dans le code (PNG @3x en base64)
/// pour ne dépendre d'aucun fichier Assets.xcassets : si ce fichier est dans le projet, les icônes s'affichent.
enum GlassIcons {
    static func image(_ name: String) -> UIImage? {
        if let cached = cache[name] { return cached }
        guard let b64 = data[name], let raw = Data(base64Encoded: b64),
              let img = UIImage(data: raw, scale: 3)?.withRenderingMode(.alwaysTemplate) else { return nil }
        cache[name] = img
        return img
    }

    private static var cache: [String: UIImage] = [:]

    private static let data: [String: String] = [
        "tab-home-off": "",
        "tab-home-on": "",
        "tab-orders-off": "",
        "tab-orders-on": "",
        "tab-products-off": "",
        "tab-products-on": "",
        "tab-menu": "",
        "act-search": "",
        "act-sidekick": "",
    ]
}
